    direct_match = query_zero_knowledge_clean_room(event.identity_signals, pub_context.first_party_id)
    if direct_match:
        // 3. Anchor to ephemeral edge pairs, decaying aggressively instead of storing an eternal ID
        session_key = derive_time_bounded_pair(direct_match, ttl="24h")
        return mint_purpose_scoped_token(session_key, consent_scope)

    // 4. For unlinked impressions, abandon 1:1 recognition in favor of privacy-preserving state
    // Tracking people across disconnected apps without consent or deterministic login is a dead end.
    return estimate_k_anonymous_reach_bucket(event.signals)
